-- Robotics/Embedded/IoT pathway ("Vector Division") Act 26 -- "ROS 2
-- Advanced" content, continuing Arc V ("Give Robots a Nervous System,"
-- Acts 25-28). World row world-vec-ros2-advanced already exists (created
-- by 20260813360000). 1 campaign, 2 operations, 12 missions (11 lessons +
-- boss), following the same campaigns -> operations -> missions ->
-- dialogue -> objectives -> challenges -> hints pattern as every other
-- pathway. No new ChallengeType needed -- reuses story_dialogue,
-- multiple_choice, drag_and_drop, investigation, interactive_diagram,
-- browser_simulation and boss_encounter. Vector Division builds deeper
-- ROS 2 introspection tooling -- DDS, QoS, TF2, URDF, robot state
-- publisher, rosbag, lifecycle nodes, composition, executors, Nav2,
-- graph debugging -- to keep mapping SUBSTRATE's exposed structure from
-- Act 25, and in the middle of that work one of Vector Division's own
-- robots throws a violent position glitch. The boss, "Transform
-- Extrapolation," resolves that glitch as an ordinary timing bug in a
-- static transform publisher's irregular publish rate -- explicitly NOT
-- SUBSTRATE-related, with SUBSTRATE's own nodes investigated and ruled
-- out. No new substrate dialogue line is added this Act; SUBSTRATE is
-- referenced only in passing as something already ruled out.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-ros2-advanced', 'world-vec-ros2-advanced', 'ros2-advanced', '5B - ROS 2 Advanced', 'Learn the deeper machinery underneath the graph -- DDS, quality of service, TF2 transforms, URDF, the robot state publisher, rosbag, lifecycle nodes, composition, executors, the navigation stack and how to debug a ROS graph -- while Vector Division keeps mapping SUBSTRATE''s exposed structure and, in the middle of that work, has to explain why one of its own robots just glitched.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-ros2-advanced-1', 'campaign-vec-ros2-advanced', 'the-transport-underneath', 'The Transport Underneath', 'DDS concepts, quality of service, TF2 transforms, URDF, the robot state publisher, and rosbag.', 1),
  ('operation-vec-ros2-advanced-2', 'campaign-vec-ros2-advanced', 'a-glitch-that-is-not-substrate', 'A Glitch That Is Not SUBSTRATE', 'Lifecycle nodes, composition, executors, the navigation stack, debugging ROS graphs, and one robot''s impossible jump.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-ros2-advanced-01', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'dds-concepts', 'DDS Concepts', 'Every topic, service and action Vector Division has ever built rides on top of one underlying transport nobody has looked at directly yet. Dr. Lin Ortega wants that layer understood before the graph gets mapped any further.', 'beginner', ARRAY['lin','byte','imani'], null, null, '{"type":"simulation","simulationId":"dds-concepts-sim"}'::jsonb, '{"xp":330,"credits":25}'::jsonb, false, 1),
  ('mission-vec-ros2-advanced-02', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'quality-of-service', 'Quality of Service', 'A publisher and a subscriber agreeing on a name and a type is not the whole contract. Lin walks through the policies that decide whether two endpoints are even willing to talk.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"quality-of-service-sim"}'::jsonb, '{"xp":330,"credits":30}'::jsonb, false, 2),
  ('mission-vec-ros2-advanced-03', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'tf2-transforms', 'TF2 Transforms', 'Nothing on a robot agrees on where anything is unless every frame''s position relative to every other frame is tracked continuously. Byte starts building the tool that reads that structure directly.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-ros2-advanced-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"tf2-transforms-sim"}'::jsonb, '{"xp":340,"credits":30}'::jsonb, false, 3),
  ('mission-vec-ros2-advanced-04', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'urdf', 'URDF', 'Before TF2 can track a robot''s frames, something has to describe what those frames actually are. Lin lays out the file format that defines a robot''s own body.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"urdf-sim"}'::jsonb, '{"xp":340,"credits":35}'::jsonb, false, 4),
  ('mission-vec-ros2-advanced-05', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'robot-state-publisher', 'Robot State Publisher', 'A URDF file is static text until something turns it into a living stream of transforms. Byte wires up the node responsible for keeping every joint and frame current, in real time.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-ros2-advanced-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"robot-state-publisher-sim"}'::jsonb, '{"xp":350,"credits":35}'::jsonb, false, 5),
  ('mission-vec-ros2-advanced-06', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-1', 'rosbag', 'rosbag', 'A live graph only shows what is happening right now. Lin wants every session recorded, so any incident that happens overnight can be replayed exactly, message for message, the next morning.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"rosbag-sim"}'::jsonb, '{"xp":350,"credits":35}'::jsonb, false, 6),
  ('mission-vec-ros2-advanced-07', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'lifecycle-nodes-concepts', 'Lifecycle Nodes Concepts', 'Overnight, one of Vector Division''s own robots threw a violent position glitch mid-move. Nobody was hurt, but Lin wants every node''s startup sequence made explicit before anyone assumes what state it was actually in.', 'beginner', ARRAY['lin','imani','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"lifecycle-nodes-sim"}'::jsonb, '{"xp":360,"credits":40}'::jsonb, false, 7),
  ('mission-vec-ros2-advanced-08', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'composition-concepts', 'Composition Concepts', 'Running every node as its own process is simple but not free -- each boundary the glitch''s data has to cross costs time Byte cannot yet account for. Lin explains the alternative.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"composition-sim"}'::jsonb, '{"xp":360,"credits":40}'::jsonb, false, 8),
  ('mission-vec-ros2-advanced-09', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'executors-concepts', 'Executors Concepts', 'Composed or not, something still has to decide which node''s callback actually runs next, and in what order. Lin wants that scheduling understood before anyone blames a race condition that might not exist.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"executors-sim"}'::jsonb, '{"xp":370,"credits":40}'::jsonb, false, 9),
  ('mission-vec-ros2-advanced-10', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'navigation-stack-overview', 'Navigation Stack Overview', 'The glitch happened mid-move, which means the navigation stack was actively driving the robot when it happened. Lin walks through what that stack actually asks for, and how often.', 'beginner', ARRAY['lin','byte'], '{"requiredMissionIds":["mission-vec-ros2-advanced-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"navigation-stack-sim"}'::jsonb, '{"xp":370,"credits":45}'::jsonb, false, 10),
  ('mission-vec-ros2-advanced-11', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'debugging-ros-graphs', 'Debugging ROS Graphs', 'Before anyone points a finger at the graph SUBSTRATE was just found sitting inside, Byte builds a clean method for debugging any ROS graph -- so the answer, whatever it is, actually earns its conclusion.', 'beginner', ARRAY['byte','lin'], '{"requiredMissionIds":["mission-vec-ros2-advanced-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"debugging-ros-graphs-sim"}'::jsonb, '{"xp":380,"credits":45}'::jsonb, false, 11),
  ('mission-vec-ros2-advanced-12', 'world-vec-ros2-advanced', 'campaign-vec-ros2-advanced', 'operation-vec-ros2-advanced-2', 'transform-extrapolation', 'Transform Extrapolation', 'Everything this Act taught, aimed at one impossible jump -- tracing it through TF2 and rosbag, proving its root cause through the robot state publisher, and ruling out SUBSTRATE''s own nodes with the same debugging method used on everything else.', 'boss', ARRAY['lin','byte','imani'], '{"requiredMissionIds":["mission-vec-ros2-advanced-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"transform-extrapolation-boss-sim"}'::jsonb, '{"xp":1950,"credits":400,"badgeIds":["transform-extrapolation"],"skillXp":{"robotics_fundamentals":280}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-ros2-advanced-01', 1, 'imani', 'The graph is exposed now. Before we map any more of SUBSTRATE''s structure on it, Dr. Lin Ortega is taking over -- TF2, rosbag, lifecycle nodes, everything underneath what Byte already built.'),
  ('mission-vec-ros2-advanced-01', 2, 'lin', 'Every topic, service and action you have used so far rides on top of one layer none of you have actually looked at: the Data Distribution Service, DDS. It is the real transport doing discovery and delivery underneath ROS 2''s own vocabulary.'),
  ('mission-vec-ros2-advanced-01', 3, 'byte', 'So when the graph shows two nodes as connected, that connection is not a ROS 2 invention. It is DDS actually finding both endpoints on the network and agreeing they match.'),
  ('mission-vec-ros2-advanced-01', 4, 'lin', 'Exactly. ROS 2 gives you nodes, topics and messages as a clean vocabulary. DDS is the standard actually doing discovery, serialization and delivery underneath that vocabulary, whether you ever look at it or not.'),

  ('mission-vec-ros2-advanced-02', 1, 'lin', 'A matching topic name and message type get two endpoints close. Quality of service, QoS, is the rest of the contract -- a set of policies both sides have to agree on before DDS will actually connect them.'),
  ('mission-vec-ros2-advanced-02', 2, 'lin', 'Reliability: best-effort drops what it cannot deliver in time, reliable retries until delivery is confirmed. Durability: volatile only reaches subscribers who were already listening, transient-local also delivers the last message to anyone who joins late. History: how many past messages the middleware keeps queued.'),
  ('mission-vec-ros2-advanced-02', 3, 'byte', 'And none of that is negotiated automatically. If a publisher and a subscriber pick incompatible QoS policies, DDS simply never forms the connection -- no error, no warning. We already found that once, on a safety topic.'),

  ('mission-vec-ros2-advanced-03', 1, 'byte', 'A robot is not one coordinate system. It is dozens -- one for the base, one for every joint, one for every sensor -- and every one of them moves relative to the others. TF2 is the library that tracks all of that as a tree of transforms over time.'),
  ('mission-vec-ros2-advanced-03', 2, 'lin', 'A transform is just the position and orientation of one frame relative to its parent frame. Ask TF2 for the transform between any two frames, at any recent time, and it walks the tree and gives you the answer.'),
  ('mission-vec-ros2-advanced-03', 3, 'byte', 'The key word is recent. TF2 keeps a rolling buffer of transforms, not an infinite history. Ask for a time outside that buffer''s trusted window and it has to guess -- extrapolate -- instead of actually knowing.'),

  ('mission-vec-ros2-advanced-04', 1, 'lin', 'TF2 cannot track frames that were never defined. URDF, the Unified Robot Description Format, is the XML file that defines a robot''s own body -- every link, every joint, and how each one connects to the next.'),
  ('mission-vec-ros2-advanced-04', 2, 'lin', 'A link is one rigid piece of the robot -- a chassis, an arm segment, a sensor mount. A joint connects two links and defines how they can move relative to each other: fixed, meaning never, or revolute, meaning it rotates within limits.'),
  ('mission-vec-ros2-advanced-04', 3, 'byte', 'So the URDF is the static blueprint. TF2''s job is to take that blueprint and keep every frame it describes updated as the robot actually moves.'),

  ('mission-vec-ros2-advanced-05', 1, 'byte', 'A URDF file by itself never moves. The robot state publisher is the node that reads a URDF, listens to the robot''s current joint positions, and publishes the resulting transform tree onto TF2, continuously, for everything else to use.'),
  ('mission-vec-ros2-advanced-05', 2, 'lin', 'Two kinds of transform come out of it. Dynamic transforms, for every joint that actually moves, published on every update. Static transforms, for connections that never change relative position -- a sensor bolted rigidly to a chassis -- which only need to be published once, or occasionally, to stay in the buffer.'),
  ('mission-vec-ros2-advanced-05', 3, 'byte', 'That distinction matters more than it sounds like it should. A static transform publisher that stops publishing regularly still looks fine to a human. TF2''s buffer does not see it that way.'),

  ('mission-vec-ros2-advanced-06', 1, 'lin', 'A live graph only shows the present. rosbag records every message on every topic you tell it to, with real timestamps, so any incident can be replayed afterward exactly as it happened -- not reconstructed from memory.'),
  ('mission-vec-ros2-advanced-06', 2, 'byte', 'Record everything relevant to TF2 and to navigation, at minimum, from every overnight run from now on. If anything goes wrong while no one is watching, I want the actual data, not a guess.'),
  ('mission-vec-ros2-advanced-06', 3, 'lin', 'Good instinct. Keep that habit -- it is about to matter sooner than either of us expects.'),

  ('mission-vec-ros2-advanced-07', 1, 'imani', 'Overnight, one of our own robots threw a violent position glitch mid-move. No collision, no injury, but the telemetry shows a jump that should not be physically possible. I want this understood before anyone assumes what caused it.'),
  ('mission-vec-ros2-advanced-07', 2, 'lin', 'Before we even look at the bag, get the node lifecycle straight. A managed lifecycle node moves through explicit states: unconfigured at creation, inactive once configured but not yet running, active once actually processing data, and finalized on shutdown.'),
  ('mission-vec-ros2-advanced-07', 3, 'lin', 'The advantage is that a node''s state is a fact you can query, not an assumption. If a node glitches, the first honest question is which state it was actually in when it happened -- not which state we assumed it was in.'),
  ('mission-vec-ros2-advanced-07', 4, 'byte', 'Confirmed from the bag: every relevant node, including the ones on the transform side, was fully active for minutes before the glitch. No startup transition, no reconfiguration, no state change anywhere near the incident.'),

  ('mission-vec-ros2-advanced-08', 1, 'byte', 'Ruling out lifecycle state took longer than it should have, because every node lives in its own process and I had to query each one separately. That overhead is exactly what composition exists to remove.'),
  ('mission-vec-ros2-advanced-08', 2, 'lin', 'Composition loads multiple nodes into a single process instead of one process each. Communication between composed nodes can skip the network transport entirely and pass data directly in memory -- lower latency, less overhead, at the cost of losing per-node process isolation.'),
  ('mission-vec-ros2-advanced-08', 3, 'lin', 'Worth knowing for later, not the answer tonight. Composition changes how nodes are packaged. It does not, on its own, explain a transform going wrong.'),

  ('mission-vec-ros2-advanced-09', 1, 'lin', 'One more layer before the bag: inside a single process, an executor is what actually decides which node''s callback runs next. A single-threaded executor runs one callback at a time, in some order, on one thread. A multi-threaded executor can run several callbacks concurrently, grouped by callback group.'),
  ('mission-vec-ros2-advanced-09', 2, 'byte', 'Which means a slow callback in a single-threaded executor can genuinely delay every other callback queued behind it on that same thread -- not a race condition, just an ordinary scheduling delay.'),
  ('mission-vec-ros2-advanced-09', 3, 'lin', 'Keep that possibility open. A publisher that is simply queued behind other work would still look, from outside, like a publisher that is running late.'),

  ('mission-vec-ros2-advanced-10', 1, 'lin', 'The glitch happened mid-move, so before touching the bag, understand what was actually driving the robot. The navigation stack is a pipeline: a costmap builds a picture of obstacles from sensor data, a global planner finds a route across it, and a local controller turns that route into moment-to-moment velocity commands.'),
  ('mission-vec-ros2-advanced-10', 2, 'byte', 'And at every one of those stages, the stack has to ask TF2 where the robot actually is, relative to the map, right now, dozens of times per second. It cannot plan or drive without a current transform in hand.'),
  ('mission-vec-ros2-advanced-10', 3, 'lin', 'Which means if TF2 ever hands the navigation stack a bad transform, the stack does not know that. It trusts the answer and drives on it immediately.'),

  ('mission-vec-ros2-advanced-11', 1, 'byte', 'Enough background. Debugging any ROS graph, including this one, follows the same method every time: read the graph honestly for what is actually connected, check each connection''s QoS and message flow, then check timing last, after structure is confirmed correct.'),
  ('mission-vec-ros2-advanced-11', 2, 'lin', 'Follow that order before you touch the SUBSTRATE question. If SUBSTRATE''s nodes are involved here, the same method that already found them once will show it plainly. If they are not, it will show that just as plainly.'),
  ('mission-vec-ros2-advanced-11', 3, 'byte', 'Running it now, on the whole graph, including every SUBSTRATE node visible since last Act. Structure is normal. QoS is normal. Their publish timing does not correlate with the glitch window at all.'),
  ('mission-vec-ros2-advanced-11', 4, 'lin', 'Then whatever this is, it is not them. Rule them out formally, in writing, and keep looking at our own side.'),

  ('mission-vec-ros2-advanced-12', 1, 'imani', 'Everything this Act taught, aimed at one impossible jump. Not a SUBSTRATE mystery this time -- just a robot that glitched, and a team that owes it a real answer.'),
  ('mission-vec-ros2-advanced-12', 2, 'lin', 'Walk it in order. What did the navigation stack actually ask TF2 for in the moment before the jump, and what did the buffer actually have available to answer with?'),
  ('mission-vec-ros2-advanced-12', 3, 'byte', 'From the bag: the local controller requested a transform for a timestamp roughly four hundred milliseconds old. TF2''s buffer had nothing that recent from one specific frame -- its most recent sample for that frame was over a second stale, well outside the trusted extrapolation window.'),
  ('mission-vec-ros2-advanced-12', 4, 'lin', 'Now trace it to a cause, not just a symptom. Which publisher was responsible for that frame, and what was it actually doing around that time?'),
  ('mission-vec-ros2-advanced-12', 5, 'byte', 'A static transform publisher on the robot itself, covering a rigidly mounted sensor frame. Its publish rate is supposed to be steady. The bag shows it firing irregularly, with gaps stretching past a second at random, for reasons unrelated to CPU load, network traffic, or anything on the SUBSTRATE side we already cleared.'),
  ('mission-vec-ros2-advanced-12', 6, 'imani', 'Say it plainly, all three pieces together, so this never gets mistaken for something it is not.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-ros2-advanced-01-o1', 'mission-vec-ros2-advanced-01', 1, 'Define DDS', 'Choose the accurate description of what DDS actually is relative to ROS 2.'),
  ('mission-vec-ros2-advanced-01-o2', 'mission-vec-ros2-advanced-01', 2, 'Judge what a connection means', 'Judge what it actually means when the graph shows two nodes as connected.'),

  ('mission-vec-ros2-advanced-02-o1', 'mission-vec-ros2-advanced-02', 1, 'Sort the QoS policies', 'Sort each behavior into the QoS policy it actually describes.'),
  ('mission-vec-ros2-advanced-02-o2', 'mission-vec-ros2-advanced-02', 2, 'Judge the silent failure', 'Judge what happens when a publisher and subscriber choose incompatible QoS policies.'),

  ('mission-vec-ros2-advanced-03-o1', 'mission-vec-ros2-advanced-03', 1, 'Define a transform', 'Choose the accurate definition of a TF2 transform.'),
  ('mission-vec-ros2-advanced-03-o2', 'mission-vec-ros2-advanced-03', 2, 'Judge the buffer''s limit', 'Judge what TF2 must do when asked for a transform outside its buffer''s trusted window.'),

  ('mission-vec-ros2-advanced-04-o1', 'mission-vec-ros2-advanced-04', 1, 'Sort link from joint', 'Sort each URDF element into a link or a joint.'),
  ('mission-vec-ros2-advanced-04-o2', 'mission-vec-ros2-advanced-04', 2, 'Judge URDF''s role', 'Judge what a URDF file actually defines versus what it does not.'),

  ('mission-vec-ros2-advanced-05-o1', 'mission-vec-ros2-advanced-05', 1, 'Define the robot state publisher', 'Choose the accurate description of what the robot state publisher node does.'),
  ('mission-vec-ros2-advanced-05-o2', 'mission-vec-ros2-advanced-05', 2, 'Tell static from dynamic', 'Sort each transform example into static or dynamic.'),

  ('mission-vec-ros2-advanced-06-o1', 'mission-vec-ros2-advanced-06', 1, 'Define rosbag''s purpose', 'Choose the accurate description of what rosbag actually records and why.'),
  ('mission-vec-ros2-advanced-06-o2', 'mission-vec-ros2-advanced-06', 2, 'Judge the replay guarantee', 'Judge why a recorded bag is more trustworthy than a memory of what happened.'),

  ('mission-vec-ros2-advanced-07-o1', 'mission-vec-ros2-advanced-07', 1, 'Order the lifecycle states', 'Order a managed lifecycle node''s states from creation to shutdown.'),
  ('mission-vec-ros2-advanced-07-o2', 'mission-vec-ros2-advanced-07', 2, 'Rule out a startup cause', 'Find the evidence ruling out a lifecycle state transition as the glitch''s cause.'),

  ('mission-vec-ros2-advanced-08-o1', 'mission-vec-ros2-advanced-08', 1, 'Define composition', 'Choose the accurate description of what composition actually changes.'),
  ('mission-vec-ros2-advanced-08-o2', 'mission-vec-ros2-advanced-08', 2, 'Judge its relevance', 'Judge whether composition, on its own, explains a transform going wrong.'),

  ('mission-vec-ros2-advanced-09-o1', 'mission-vec-ros2-advanced-09', 1, 'Tell the executors apart', 'Choose the accurate distinction between a single-threaded and multi-threaded executor.'),
  ('mission-vec-ros2-advanced-09-o2', 'mission-vec-ros2-advanced-09', 2, 'Judge the scheduling delay', 'Judge what a slow callback can do to other callbacks queued behind it on the same thread.'),

  ('mission-vec-ros2-advanced-10-o1', 'mission-vec-ros2-advanced-10', 1, 'Order the navigation pipeline', 'Order the navigation stack''s stages from sensing to velocity command.'),
  ('mission-vec-ros2-advanced-10-o2', 'mission-vec-ros2-advanced-10', 2, 'Judge the transform dependency', 'Judge how often the navigation stack actually needs a current transform from TF2.'),

  ('mission-vec-ros2-advanced-11-o1', 'mission-vec-ros2-advanced-11', 1, 'Order the debugging method', 'Order the steps of debugging a ROS graph from structure to timing.'),
  ('mission-vec-ros2-advanced-11-o2', 'mission-vec-ros2-advanced-11', 2, 'Rule out SUBSTRATE', 'Find the evidence ruling out SUBSTRATE''s exposed nodes as the glitch''s cause.'),

  ('mission-vec-ros2-advanced-12-o1', 'mission-vec-ros2-advanced-12', 1, 'Trace the missing transform', 'Find the evidence proving the navigation stack requested a transform for a timestamp the buffer had no recent data for.'),
  ('mission-vec-ros2-advanced-12-o2', 'mission-vec-ros2-advanced-12', 2, 'Prove the root cause', 'Find the evidence proving the static transform publisher''s irregular publish rate is the actual root cause.'),
  ('mission-vec-ros2-advanced-12-o3', 'mission-vec-ros2-advanced-12', 3, 'Confirm SUBSTRATE is unrelated', 'Find the evidence confirming SUBSTRATE''s publish timing is independently normal and unrelated to the glitch.'),
  ('mission-vec-ros2-advanced-12-o4', 'mission-vec-ros2-advanced-12', 4, 'State the diagnosis', 'Having traced the missing transform, proven the root cause, and ruled out SUBSTRATE, state the full diagnosis.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-ros2-advanced-01-o1-c1', 'mission-vec-ros2-advanced-01-o1', 1, 'multiple_choice', 'DDS is best described as...', '{"question":"DDS is best described as...","options":[{"id":"a","text":"A ROS 2 invention with no existence outside it"},{"id":"b","text":"The underlying transport standard that actually performs discovery, serialization and delivery beneath ROS 2''s node, topic and message vocabulary"},{"id":"c","text":"A replacement for URDF"},{"id":"d","text":"A debugging tool for reading logs"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-01-o2-c1', 'mission-vec-ros2-advanced-01-o2', 1, 'multiple_choice', 'When the graph shows two nodes as connected, what does that actually mean?', '{"question":"When the graph shows two nodes as connected, what does that actually mean?","options":[{"id":"a","text":"ROS 2 has manually wired the two nodes together"},{"id":"b","text":"DDS has actually discovered both endpoints on the network and confirmed their names, types and policies are compatible"},{"id":"c","text":"The two nodes are running in the same process"},{"id":"d","text":"Nothing verifiable -- the graph display is only a guess"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-02-o1-c1', 'mission-vec-ros2-advanced-02-o1', 1, 'drag_and_drop', 'Sort each behavior into the QoS policy it actually describes.', '{"items":[{"id":"i1","text":"Retries delivery until it is confirmed received"},{"id":"i2","text":"Delivers the last message even to a subscriber that joins late"},{"id":"i3","text":"Drops a message it cannot deliver in time rather than retrying"},{"id":"i4","text":"Keeps a fixed number of past messages queued for new subscribers"}],"targets":[{"id":"reliable","label":"Reliability: reliable"},{"id":"transient-local","label":"Durability: transient-local"},{"id":"best-effort","label":"Reliability: best-effort"},{"id":"history","label":"History depth"}]}'::jsonb, '{"correctMapping":{"i1":"reliable","i2":"transient-local","i3":"best-effort","i4":"history"}}'::jsonb),
  ('mission-vec-ros2-advanced-02-o2-c1', 'mission-vec-ros2-advanced-02-o2', 1, 'multiple_choice', 'A publisher and subscriber choose incompatible QoS policies. What happens?', '{"question":"A publisher and subscriber choose incompatible QoS policies. What happens?","options":[{"id":"a","text":"DDS raises a clear error naming the mismatch"},{"id":"b","text":"The middleware never forms the connection at all, silently -- no error on either side"},{"id":"c","text":"The connection forms but delivers corrupted messages"},{"id":"d","text":"QoS is renegotiated automatically to whichever policy is stricter"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-03-o1-c1', 'mission-vec-ros2-advanced-03-o1', 1, 'multiple_choice', 'A TF2 transform is...', '{"question":"A TF2 transform is...","options":[{"id":"a","text":"A message type used for sensor data"},{"id":"b","text":"The position and orientation of one coordinate frame relative to its parent frame, tracked over time"},{"id":"c","text":"A URDF file itself"},{"id":"d","text":"A fixed constant that never changes for any robot"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-03-o2-c1', 'mission-vec-ros2-advanced-03-o2', 1, 'multiple_choice', 'TF2 is asked for a transform at a time outside its buffer''s trusted window. What must it do?', '{"question":"TF2 is asked for a transform at a time outside its buffer''s trusted window. What must it do?","options":[{"id":"a","text":"Refuse to answer under any circumstance"},{"id":"b","text":"Extrapolate beyond the data it actually has, producing an answer that can be confidently wrong"},{"id":"c","text":"Automatically expand its buffer to cover any requested time"},{"id":"d","text":"Return the exact same transform every time, regardless of the requested time"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-04-o1-c1', 'mission-vec-ros2-advanced-04-o1', 1, 'drag_and_drop', 'Sort each URDF element into a link or a joint.', '{"items":[{"id":"i1","text":"A rigid arm segment with its own mass and shape"},{"id":"i2","text":"A rotating connection between two arm segments with defined limits"},{"id":"i3","text":"A sensor mount rigidly fixed to the chassis"},{"id":"i4","text":"A fixed connection that never allows relative motion between two parts"}],"targets":[{"id":"link","label":"Link"},{"id":"joint","label":"Joint"}]}'::jsonb, '{"correctMapping":{"i1":"link","i2":"joint","i3":"link","i4":"joint"}}'::jsonb),
  ('mission-vec-ros2-advanced-04-o2-c1', 'mission-vec-ros2-advanced-04-o2', 1, 'multiple_choice', 'A URDF file actually defines...', '{"question":"A URDF file actually defines...","options":[{"id":"a","text":"The robot''s current live position at runtime"},{"id":"b","text":"The static blueprint of the robot''s body -- its links, its joints, and how each connects to the next"},{"id":"c","text":"The QoS policy every topic on the robot must use"},{"id":"d","text":"The robot''s navigation route"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-05-o1-c1', 'mission-vec-ros2-advanced-05-o1', 1, 'multiple_choice', 'The robot state publisher node does what?', '{"question":"The robot state publisher node does what?","options":[{"id":"a","text":"Writes the URDF file to disk"},{"id":"b","text":"Reads a URDF, listens to current joint positions, and publishes the resulting transform tree onto TF2 continuously"},{"id":"c","text":"Plans a path for the robot to follow"},{"id":"d","text":"Records rosbag files"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-05-o2-c1', 'mission-vec-ros2-advanced-05-o2', 1, 'drag_and_drop', 'Sort each transform into static or dynamic.', '{"items":[{"id":"i1","text":"The transform for an arm joint that moves continuously as the robot works"},{"id":"i2","text":"The transform between a chassis frame and a sensor rigidly bolted to it, which never changes"},{"id":"i3","text":"The transform for a wheel that is constantly rotating"},{"id":"i4","text":"The transform between two frames on a fixed camera mount that never moves relative to the chassis"}],"targets":[{"id":"dynamic","label":"Dynamic transform"},{"id":"static","label":"Static transform"}]}'::jsonb, '{"correctMapping":{"i1":"dynamic","i2":"static","i3":"dynamic","i4":"static"}}'::jsonb),

  ('mission-vec-ros2-advanced-06-o1-c1', 'mission-vec-ros2-advanced-06-o1', 1, 'multiple_choice', 'rosbag actually records...', '{"question":"rosbag actually records...","options":[{"id":"a","text":"Only error messages"},{"id":"b","text":"Every message on every topic it is told to watch, with real timestamps, so an incident can be replayed exactly as it happened"},{"id":"c","text":"A summary of node CPU usage only"},{"id":"d","text":"Nothing while the robot is actively moving"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-06-o2-c1', 'mission-vec-ros2-advanced-06-o2', 1, 'multiple_choice', 'Why is a recorded rosbag more trustworthy than a human''s memory of an overnight incident?', '{"question":"Why is a recorded rosbag more trustworthy than a human''s memory of an overnight incident?","options":[{"id":"a","text":"It is not more trustworthy, memory is just as reliable"},{"id":"b","text":"It preserves the actual data and real timestamps exchanged at the time, independent of who was watching or what anyone later assumed happened"},{"id":"c","text":"rosbag automatically diagnoses the cause of any incident on its own"},{"id":"d","text":"Bags only ever record successful operation, never failures"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-07-o1-c1', 'mission-vec-ros2-advanced-07-o1', 1, 'interactive_diagram', 'Order a managed lifecycle node''s states from creation to shutdown.', '{"diagramId":"lifecycle-node-states","hotspots":[{"id":"unconfigured","label":"Unconfigured","explanation":"The node exists but has not yet been configured."},{"id":"inactive","label":"Inactive","explanation":"The node is configured but not yet processing data."},{"id":"active","label":"Active","explanation":"The node is fully running and processing data."},{"id":"finalized","label":"Finalized","explanation":"The node has shut down and released its resources."}],"task":"Order the lifecycle states from creation to shutdown."}'::jsonb, '{"correctOrderIds":["unconfigured","inactive","active","finalized"]}'::jsonb),
  ('mission-vec-ros2-advanced-07-o2-c1', 'mission-vec-ros2-advanced-07-o2', 1, 'investigation', 'Which evidence rules out a lifecycle state transition as the glitch''s cause?', '{"evidence":[{"id":"e1","label":"Lifecycle log","detail":"Every relevant node, including transform-side nodes, was already fully active for minutes before the glitch, with no state transition anywhere near the incident"},{"id":"e2","label":"Facilities note","detail":"The robot''s chassis passed its last physical inspection"},{"id":"e3","label":"Power log","detail":"Facility-wide power draw stayed within normal range overnight"}],"question":"Which evidence rules out a lifecycle state transition as the glitch''s cause?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-ros2-advanced-08-o1-c1', 'mission-vec-ros2-advanced-08-o1', 1, 'multiple_choice', 'Composition actually changes...', '{"question":"Composition actually changes...","options":[{"id":"a","text":"What a node decides internally"},{"id":"b","text":"Whether multiple nodes run in one process, sharing memory for lower-latency communication instead of running one process each"},{"id":"c","text":"The QoS policy of every topic automatically"},{"id":"d","text":"The contents of a URDF file"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-08-o2-c1', 'mission-vec-ros2-advanced-08-o2', 1, 'multiple_choice', 'Does composition, on its own, explain a transform going wrong?', '{"question":"Does composition, on its own, explain a transform going wrong?","options":[{"id":"a","text":"Yes, composed nodes cannot publish transforms correctly"},{"id":"b","text":"No -- composition changes how nodes are packaged and communicate, it does not by itself cause a transform''s data to be wrong"},{"id":"c","text":"Yes, but only for static transforms"},{"id":"d","text":"It is impossible to know without more information about the CPU"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-09-o1-c1', 'mission-vec-ros2-advanced-09-o1', 1, 'multiple_choice', 'The difference between a single-threaded and multi-threaded executor is...', '{"question":"The difference between a single-threaded and multi-threaded executor is...","options":[{"id":"a","text":"They are two names for the same scheduling behavior"},{"id":"b","text":"A single-threaded executor runs one callback at a time on one thread; a multi-threaded executor can run several callbacks concurrently, grouped by callback group"},{"id":"c","text":"Only multi-threaded executors can run lifecycle nodes"},{"id":"d","text":"Single-threaded executors cannot run more than one node"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-09-o2-c1', 'mission-vec-ros2-advanced-09-o2', 1, 'multiple_choice', 'What can a slow callback do to other callbacks queued behind it on a single-threaded executor?', '{"question":"What can a slow callback do to other callbacks queued behind it on a single-threaded executor?","options":[{"id":"a","text":"Nothing, callbacks always run at their scheduled time regardless"},{"id":"b","text":"Genuinely delay them, since only one callback can run on that thread at a time -- an ordinary scheduling delay, not a race condition"},{"id":"c","text":"Cause them to run twice"},{"id":"d","text":"Automatically move them to a different executor"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-10-o1-c1', 'mission-vec-ros2-advanced-10-o1', 1, 'interactive_diagram', 'Order the navigation stack''s stages from sensing to velocity command.', '{"diagramId":"navigation-stack-pipeline","hotspots":[{"id":"sensors","label":"Sensor data","explanation":"Raw sensor readings feed into the stack."},{"id":"costmap","label":"Costmap","explanation":"Sensor data is turned into a map of obstacles and free space."},{"id":"planner","label":"Global planner","explanation":"A route is planned across the costmap toward the goal."},{"id":"controller","label":"Local controller","explanation":"The planned route is turned into moment-to-moment velocity commands."}],"task":"Order the navigation stack''s stages from sensor data to a velocity command."}'::jsonb, '{"correctOrderIds":["sensors","costmap","planner","controller"]}'::jsonb),
  ('mission-vec-ros2-advanced-10-o2-c1', 'mission-vec-ros2-advanced-10-o2', 1, 'multiple_choice', 'How often does the navigation stack actually need a current transform from TF2 while driving?', '{"question":"How often does the navigation stack actually need a current transform from TF2 while driving?","options":[{"id":"a","text":"Once, at the very start of the route"},{"id":"b","text":"Continuously, dozens of times per second, at every stage from costmap to controller, and it trusts whatever answer TF2 gives"},{"id":"c","text":"Only when the goal changes"},{"id":"d","text":"Never -- the navigation stack does not use TF2"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-ros2-advanced-11-o1-c1', 'mission-vec-ros2-advanced-11-o1', 1, 'interactive_diagram', 'Order the steps of debugging a ROS graph from structure to timing.', '{"diagramId":"debugging-ros-graphs-method","hotspots":[{"id":"structure","label":"Read the graph structure","explanation":"Honestly identify what is actually connected to what, right now."},{"id":"qos","label":"Check QoS and message flow","explanation":"Confirm connections are compatible and messages are actually flowing."},{"id":"timing","label":"Check timing last","explanation":"Only after structure and flow are confirmed correct, examine timing."}],"task":"Order the debugging steps from structure to timing."}'::jsonb, '{"correctOrderIds":["structure","qos","timing"]}'::jsonb),
  ('mission-vec-ros2-advanced-11-o2-c1', 'mission-vec-ros2-advanced-11-o2', 1, 'investigation', 'Which evidence rules out SUBSTRATE''s exposed nodes as the glitch''s cause?', '{"evidence":[{"id":"e1","label":"Graph scan","detail":"SUBSTRATE''s nodes remain visible on the live graph, publishing on the same forgotten interfaces found last Act"},{"id":"e2","label":"Timing correlation check","detail":"SUBSTRATE nodes'' publish timing was compared directly against the glitch window and shows no correlation at all -- their activity is independently steady and unrelated"},{"id":"e3","label":"Facilities note","detail":"SUBSTRATE has not spoken again since its single line last Act"}],"question":"Which evidence rules out SUBSTRATE''s exposed nodes as the glitch''s cause?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-ros2-advanced-12-o1-c1', 'mission-vec-ros2-advanced-12-o1', 1, 'investigation', 'Find the evidence proving the navigation stack requested a transform for a timestamp the buffer had no recent data for.', '{"evidence":[{"id":"e1","label":"Bag replay, controller request","detail":"The local controller requested a transform for a specific sensor frame at a timestamp roughly four hundred milliseconds before the glitch"},{"id":"e2","label":"Bag replay, buffer state","detail":"TF2''s buffer for that exact frame had no sample newer than one full second before the request, well outside the trusted extrapolation window"},{"id":"e3","label":"Power log","detail":"The robot''s battery level was within normal operating range at the time"},{"id":"e4","label":"Process list","detail":"Every node was running with normal CPU and memory usage at the time"}],"question":"Which evidence proves the navigation stack asked TF2 for a transform the buffer could not honestly answer?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-ros2-advanced-12-o2-c1', 'mission-vec-ros2-advanced-12-o2', 1, 'browser_simulation', 'Which raw diagnostic record identifies the actual root cause of the missing transform?', '{"screen":"ROSBAG REPLAY -- STATIC TRANSFORM PUBLISHER -- SENSOR FRAME","question":"Which raw diagnostic record identifies the actual root cause of the missing transform?","records":[{"id":"r1","code":"LIFECYCLE_ACTIVE","detail":"Publisher node lifecycle state: active, no transitions in this window"},{"id":"r2","code":"PUBLISH_INTERVAL_IRREGULAR","detail":"Static transform publisher''s publish interval swings randomly between 40 milliseconds and over 1200 milliseconds, with no correlation to CPU load, network traffic or any SUBSTRATE-attributed node"},{"id":"r3","code":"CPU_NOMINAL","detail":"Host CPU usage stayed under 30 percent throughout the window"},{"id":"r4","code":"NETWORK_NOMINAL","detail":"No packet loss or latency spike detected on the local network segment"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),
  ('mission-vec-ros2-advanced-12-o3-c1', 'mission-vec-ros2-advanced-12-o3', 1, 'multiple_choice', 'What does the timing correlation check actually confirm about SUBSTRATE''s role in this glitch?', '{"question":"What does the timing correlation check actually confirm about SUBSTRATE''s role in this glitch?","options":[{"id":"a","text":"SUBSTRATE deliberately delayed the static transform publisher"},{"id":"b","text":"SUBSTRATE''s nodes were investigated and their publish timing is independently normal and unrelated -- this is an ordinary timing bug in Vector Division''s own code"},{"id":"c","text":"SUBSTRATE cannot be ruled out without more data"},{"id":"d","text":"SUBSTRATE is responsible because it is present on the same graph"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-ros2-advanced-12-o4-c1', 'mission-vec-ros2-advanced-12-o4', 1, 'boss_encounter', 'Having traced the missing transform, proven the root cause, and ruled out SUBSTRATE, state the full diagnosis.', '{"stages":[{"objectiveRef":"mission-vec-ros2-advanced-12-o1","label":"Trace the missing transform"},{"objectiveRef":"mission-vec-ros2-advanced-12-o2","label":"Prove the root cause"},{"objectiveRef":"mission-vec-ros2-advanced-12-o3","label":"Confirm SUBSTRATE is unrelated"}],"task":"State the diagnosis in one sentence: the navigation stack asked TF2 for a transform the buffer had nothing recent enough to answer honestly, TF2 extrapolated beyond its trusted window instead of refusing, and the root cause is a static transform publisher on the robot itself with an irregular publish rate -- confirmed unrelated to SUBSTRATE, whose own nodes were checked and cleared."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-ros2-advanced-12-o1","mission-vec-ros2-advanced-12-o2","mission-vec-ros2-advanced-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-ros2-advanced-01-o1-c1', 'orientation', 'ROS 2''s node/topic vocabulary has to actually run on something -- ask what that something is.', 10, 1),
  ('mission-vec-ros2-advanced-01-o1-c1', 'solution', 'DDS is the underlying transport standard doing real discovery, serialization and delivery beneath ROS 2''s own vocabulary.', 20, 2),
  ('mission-vec-ros2-advanced-01-o2-c1', 'orientation', 'A graph display is not just decoration -- ask what has to actually be true underneath it.', 10, 1),
  ('mission-vec-ros2-advanced-01-o2-c1', 'solution', 'It means DDS has actually discovered both endpoints and confirmed their names, types and policies match -- not just a claim.', 20, 2),

  ('mission-vec-ros2-advanced-02-o1-c1', 'orientation', 'Ask which policy governs delivery guarantees, which governs late joiners, and which governs how much history is kept.', 10, 1),
  ('mission-vec-ros2-advanced-02-o1-c1', 'solution', 'Retry-until-confirmed is reliable. Delivering the last message to late joiners is transient-local. Dropping rather than retrying is best-effort. Keeping a fixed queue of past messages is history depth.', 20, 2),
  ('mission-vec-ros2-advanced-02-o2-c1', 'orientation', 'You have seen this exact silent failure before, on a safety topic.', 10, 1),
  ('mission-vec-ros2-advanced-02-o2-c1', 'solution', 'Incompatible QoS means the middleware never forms the connection at all, silently, with no error on either side.', 20, 2),

  ('mission-vec-ros2-advanced-03-o1-c1', 'orientation', 'A transform is not about the robot as a whole -- it is about one frame relative to one other frame.', 10, 1),
  ('mission-vec-ros2-advanced-03-o1-c1', 'solution', 'A transform is the position and orientation of a frame relative to its parent, tracked over time.', 20, 2),
  ('mission-vec-ros2-advanced-03-o2-c1', 'orientation', 'The buffer only actually knows what it has recently received.', 10, 1),
  ('mission-vec-ros2-advanced-03-o2-c1', 'solution', 'Outside the trusted window, TF2 has to extrapolate beyond real data -- an answer that can be confidently wrong.', 20, 2),

  ('mission-vec-ros2-advanced-04-o1-c1', 'orientation', 'A link is a rigid piece. A joint is the connection that allows or forbids motion between two links.', 10, 1),
  ('mission-vec-ros2-advanced-04-o1-c1', 'solution', 'Links: the arm segment and the sensor mount. Joints: the rotating connection and the fixed connection -- both describe relationships between links.', 20, 2),
  ('mission-vec-ros2-advanced-04-o2-c1', 'orientation', 'Ask whether URDF changes as the robot moves, or stays the same.', 10, 1),
  ('mission-vec-ros2-advanced-04-o2-c1', 'solution', 'URDF defines the static blueprint of the robot''s body -- it does not track live position, that is TF2''s job.', 20, 2),

  ('mission-vec-ros2-advanced-05-o1-c1', 'orientation', 'The node turns two inputs -- a static file and live joint data -- into one continuous output.', 10, 1),
  ('mission-vec-ros2-advanced-05-o1-c1', 'solution', 'It reads a URDF, listens to current joint positions, and publishes the resulting transform tree onto TF2 continuously.', 20, 2),
  ('mission-vec-ros2-advanced-05-o2-c1', 'orientation', 'Ask whether the relative position between two frames actually changes as the robot moves.', 10, 1),
  ('mission-vec-ros2-advanced-05-o2-c1', 'solution', 'Dynamic: the moving arm joint and the rotating wheel. Static: the rigidly bolted sensor and the fixed camera mount -- their relative position never changes.', 20, 2),

  ('mission-vec-ros2-advanced-06-o1-c1', 'orientation', 'Think about what a live graph cannot show you once the moment has passed.', 10, 1),
  ('mission-vec-ros2-advanced-06-o1-c1', 'solution', 'rosbag records every message on watched topics with real timestamps, so an incident can be replayed exactly, not guessed at.', 20, 2),
  ('mission-vec-ros2-advanced-06-o2-c1', 'orientation', 'Ask what a bag preserves that a person''s recollection cannot.', 10, 1),
  ('mission-vec-ros2-advanced-06-o2-c1', 'solution', 'A bag preserves the actual data and timestamps exchanged at the time, independent of who was watching or what anyone assumed afterward.', 20, 2),

  ('mission-vec-ros2-advanced-07-o1-c1', 'orientation', 'A node cannot process data before it is configured, and cannot be configured before it exists.', 10, 1),
  ('mission-vec-ros2-advanced-07-o1-c1', 'solution', 'Unconfigured, then inactive, then active, then finalized -- each state depends on the one before it.', 20, 2),
  ('mission-vec-ros2-advanced-07-o2-c1', 'orientation', 'Look for evidence about what state the nodes were actually in, not evidence about the robot''s hardware.', 10, 1),
  ('mission-vec-ros2-advanced-07-o2-c1', 'solution', 'e1: every relevant node was already fully active for minutes before the glitch, with no state transition anywhere near it.', 20, 2),

  ('mission-vec-ros2-advanced-08-o1-c1', 'orientation', 'Composition is about where nodes run, not about what they decide.', 10, 1),
  ('mission-vec-ros2-advanced-08-o1-c1', 'solution', 'It loads multiple nodes into one process, allowing lower-latency in-memory communication instead of one process each.', 20, 2),
  ('mission-vec-ros2-advanced-08-o2-c1', 'orientation', 'Ask whether packaging nodes differently changes the correctness of the data they publish.', 10, 1),
  ('mission-vec-ros2-advanced-08-o2-c1', 'solution', 'No -- composition changes packaging and communication overhead, not whether a transform''s underlying data is correct.', 20, 2),

  ('mission-vec-ros2-advanced-09-o1-c1', 'orientation', 'Ask how many callbacks can actually run at the same literal instant in each case.', 10, 1),
  ('mission-vec-ros2-advanced-09-o1-c1', 'solution', 'Single-threaded runs one callback at a time on one thread. Multi-threaded can run several concurrently, grouped by callback group.', 20, 2),
  ('mission-vec-ros2-advanced-09-o2-c1', 'orientation', 'One thread can only do one thing at a time -- ask what that means for everything else waiting.', 10, 1),
  ('mission-vec-ros2-advanced-09-o2-c1', 'solution', 'A slow callback genuinely delays everything queued behind it on that thread -- an ordinary scheduling delay, not a race condition.', 20, 2),

  ('mission-vec-ros2-advanced-10-o1-c1', 'orientation', 'Nothing can be planned before obstacles are known, and nothing can be commanded before a route is planned.', 10, 1),
  ('mission-vec-ros2-advanced-10-o1-c1', 'solution', 'Sensor data, then costmap, then global planner, then local controller -- each stage depends on the one before it.', 20, 2),
  ('mission-vec-ros2-advanced-10-o2-c1', 'orientation', 'Ask how many times per second a moving robot actually needs to know where it is.', 10, 1),
  ('mission-vec-ros2-advanced-10-o2-c1', 'solution', 'Continuously, dozens of times per second, at every stage -- and the stack trusts whatever TF2 answers with.', 20, 2),

  ('mission-vec-ros2-advanced-11-o1-c1', 'orientation', 'Confirm what is connected before questioning how fast it is connected.', 10, 1),
  ('mission-vec-ros2-advanced-11-o1-c1', 'solution', 'Structure first, then QoS and message flow, then timing last -- timing is only meaningful once structure is confirmed correct.', 20, 2),
  ('mission-vec-ros2-advanced-11-o2-c1', 'orientation', 'Presence on the graph is not the same as involvement in the incident -- look for the timing comparison specifically.', 10, 1),
  ('mission-vec-ros2-advanced-11-o2-c1', 'solution', 'e2: SUBSTRATE nodes'' publish timing shows no correlation with the glitch window at all -- their activity is independently steady.', 20, 2),

  ('mission-vec-ros2-advanced-12-o1-c1', 'orientation', 'Compare what was requested against what the buffer actually had on hand for that exact frame.', 10, 1),
  ('mission-vec-ros2-advanced-12-o1-c1', 'concept', 'A request for a recent timestamp is only answerable if the buffer has a sample close enough to it. A gap of over a second against a request for four hundred milliseconds ago is well outside any reasonable trusted window.', 20, 2),
  ('mission-vec-ros2-advanced-12-o1-c1', 'solution', 'e2: the buffer''s most recent sample for that frame was over a second stale against a four-hundred-millisecond-old request -- outside the trusted window, forcing extrapolation.', 30, 3),
  ('mission-vec-ros2-advanced-12-o2-c1', 'orientation', 'Three of the four records are routine status checks -- only one describes the publisher''s actual behavior over time.', 10, 1),
  ('mission-vec-ros2-advanced-12-o2-c1', 'solution', 'r2, PUBLISH_INTERVAL_IRREGULAR, is the root cause -- the static transform publisher''s wildly uneven interval, unrelated to CPU, network, or SUBSTRATE.', 20, 2),
  ('mission-vec-ros2-advanced-12-o3-c1', 'orientation', 'The check already ran in the previous mission -- ask what it actually found.', 10, 1),
  ('mission-vec-ros2-advanced-12-o3-c1', 'solution', 'SUBSTRATE''s nodes were investigated and their timing is independently normal -- this is an ordinary timing bug in Vector Division''s own code, not a SUBSTRATE incident.', 20, 2),
  ('mission-vec-ros2-advanced-12-o4-c1', 'orientation', 'State what was requested, what was actually available, why the buffer answered wrong, what caused that, and who was cleared.', 15, 1),
  ('mission-vec-ros2-advanced-12-o4-c1', 'solution', 'The navigation stack requested a transform the TF2 buffer had no recent data for, TF2 extrapolated instead of refusing, and the root cause is the robot''s own static transform publisher firing at an irregular rate -- confirmed unrelated to SUBSTRATE, whose nodes were checked and cleared.', 25, 2);
